-- ============================================================================
-- عنقود المواليد: ثلاثة أنقاض ← دليل واحد — ولغز الأرشفة يُكشف على الشاشة
-- ============================================================================
-- birth-registration-turkey (357 حرفاً، 37 قراءة) يُعاد بناؤه دليلاً كاملاً
-- على المادة 15 من قانون 5490 — المثبَّتة أصلاً في دليل جواز الطفل عندنا —
-- ويتقاعد النقضان kimlik-newborn-addition وfamily-birth-registration-flow
-- (التحويلات 301 في next.config.ts).
--
-- فخّان تفاداهما هذا الملف:
-- 1. id هذا الصفّ لا يساوي slug (فُحص حيّاً) — فالإدماج UPDATE لا INSERT،
--    وإلا أنشأ ON CONFLICT (id) صفّاً ثانياً بالـslug نفسه بصمت.
-- 2. صفحة إجازة الأمومة تربط النقض المتقاعد — رابطها يُعاد كتابته بإبرة
--    قصيرة بلا أسطر (فلا يطالها عطب CRLF).
--
-- ── ولغز الأرشفة ──────────────────────────────────────────────────────
-- ملفّا التوحيد السابقان أرشفا أنقاضهما في بلوك DO بمعالج استثناء. فُحص
-- حيّاً بعد تشغيلك لهما: الأنقاض الخمسة كلّها ما زالت approved — المعالج
-- التقط خطأً في المرّتين ونصُّه ضاع في رسائل المحرّر. هذا الملف يجعله
-- مقروءاً: الخطأ يُلتقط في متغيّر جلسة ويطبعه استعلام المراجعة الأخير،
-- ومعه استعلامان يعرضان قيود CHECK والمشغّلات (triggers) على جدول articles
-- — فهما المشتبهان. والأنقاض السبعة كلّها يُعاد محاولتها هنا دفعةً واحدة.
-- وسلوك الزائر صحيح في كل الأحوال: كل slug متقاعد له 301.
--
-- آمن لإعادة التشغيل.
-- ============================================================================

-- الدليل — UPDATE بالـslug (لا upsert: id هذا الصف يخالف slug)
UPDATE articles SET
    title = 'تسجيل المولود الجديد في تركيا 2026: مهلة الثلاثين يوماً، وFormül A، وخطوة كل جنسية ووضع', intro = 'وُلد طفلكم في تركيا؟ ثلاثة أشياء تحكم كل ما بعدها: التبليغ إلزامي خلال 30 يوماً (والمشفى ملزم بدوره خلال 5 أيام عمل — لكن تحقّقوا بأنفسكم)، وبيان الولادة متعدد اللغات Formül A هو الوثيقة التي تُبنى عليها القنصلية والجواز، والولادة هنا لا تمنح الجنسية التركية. ثم يفترق الطريق بحسب وضعكم: إضافة الطفل للكملك، أو ترتيب إقامته، ثم الشقّ السوري بترتيبه الصحيح.', details = '<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>الخلاصة</strong></p><p style="margin:0;">التبليغ عن المولود <strong>إلزامي خلال 30 يوماً</strong> إلى مديرية النفوس أو المشفى نفسه. اطلب من النفوس <strong>بيان الولادة متعدد اللغات (Formül A)</strong> — هو الوثيقة التي يُبنى عليها كل ما بعدها. والولادة في تركيا <strong>لا تمنح الجنسية التركية</strong>: الطفل يتبع وضع والديه.</p></div><h2>واجب التبليغ — بنصّ القانون</h2><p>قانون خدمات النفوس رقم 5490، المادة 15:</p><table><thead><tr><th>الحالة</th><th>القاعدة</th></tr></thead><tbody><tr><td>كل مولود حيّ داخل تركيا</td><td>تبليغ إلزامي خلال <strong>30 يوماً</strong> إلى مديرية النفوس (Nüfus Müdürlüğü) أو إلى المشفى الذي جرت فيه الولادة (م15/1)</td></tr><tr><td>الولادة في مشفى</td><td>المشفى نفسه ملزم بتبليغ النفوس خلال <strong>5 أيام عمل</strong> (م15/2) — لكن لا تتّكل على ذلك: تحقّق بنفسك من أنّ القيد تمّ</td></tr><tr><td>الولادة في البيت بلا كادر صحي</td><td>التبليغ إلى النفوس <strong>ببيان شفهي</strong> (م15/4) — فغياب تقرير المشفى لا يمنع القيد</td></tr><tr><td>على من يقع الواجب؟</td><td>الولي أو الوصي أو القيّم؛ وعند غيابهم الجدّ أو الجدّة أو الإخوة البالغون أو من يكون الطفل عنده (م15/5)</td></tr></tbody></table><p>وإن فاتتك الثلاثون يوماً: <strong>سجّل فوراً ولا تؤجّل أكثر</strong> — التأخّر لا يمنع القيد، وكلّ ما بعده من معاملات الطفل متوقّف عليه.</p><h2>الوثيقة التي تطلبها بالاسم: Formül A</h2><p>بعد القيد اطلب من النفوس <strong>بيان الولادة متعدد اللغات</strong> (<span dir="ltr">Formül A</span>). هو المستند الذي تتعامل به القنصليات والجهات الخارجية، وطلبُه في اليوم نفسه يوفّر عليك مراجعةً كاملة لاحقاً.</p><h2>هل يأخذ الطفل الجنسية التركية؟</h2><p><strong>لا.</strong> تركيا لا تمنح الجنسية بحقّ الأرض؛ المولود يتبع جنسية والديه ووضعهما القانوني. وما يتغيّر بحسب وضع الوالدين هو الخطوة التالية:</p><h3>والدان على الحماية المؤقتة (كملك)</h3><p>يُضاف الطفل إلى قيد العائلة لدى <strong>مديرية الهجرة في ولايتكم</strong> ويصدر له رقم أجنبي يبدأ بـ99 وبطاقته. راجعوا المديرية بأسرع ما يمكن ومعكم إثبات الولادة وكملك الوالدين — فالصحة والتطعيم وكلّ معاملات الطفل معلّقة على رقمه. (<a href="/article/kimlik-temporary-protection-syria-2026">دليل الكملك والحماية المؤقتة</a>، و<a href="/article/kimlik-data-update">تحديث البيانات والعنوان</a>.)</p><h3>والدان بإقامة (سياحية، عمل، عائلية…)</h3><p>الطفل يحتاج ترتيب وضعه الإقامي هو أيضاً — لا يُغطّى تلقائياً بإقامة والديه إلى ما لا نهاية. راجع مديرية الهجرة في ولايتك مبكراً واسأل عن إقامة الطفل بحسب نوع إقامتكما، ولا تبنِ على مهلة سمعتها من غير المديرية.</p><h3>ثم الشقّ السوري: التسجيل القنصلي والجواز — بترتيبه الصحيح</h3><p>لمن أراد تثبيت الطفل في السجلّات السورية واستخراج جوازه: الترتيب الصحيح ستّ مراحل تبدأ من القيد التركي أعلاه ولا تنتهي بالجواز إلا بعد تثبيت الواقعة في سورية — الدليل الكامل: <a href="/article/children-passport-syria">جواز سفر سوري لطفل وُلد في تركيا: الترتيب الصحيح للخطوات</a>. وابدأ بتصديق شهادة الولادة قبل مراجعة البعثة.</p><h2>أسئلة متكرّرة</h2><h3>المشفى لم يعطنا شيئاً — ماذا نفعل؟</h3><p>تقرير الولادة حقّكم، اطلبوه. وسواء أعطاكم أم لا: قيد النفوس هو الأصل، وFormül A تصدر من النفوس لا من المشفى.</p><h3>وُلد الطفل قبل أن نحدّث عنواننا — هل نسجّله على العنوان القديم؟</h3><p>سجّلوا الولادة أولاً ولا تربطوها بمعاملة العنوان؛ ثم عالجوا العنوان في مساره (<a href="/article/kimlik-data-update">تحديث البيانات</a>). تعليق القيد على معاملة أخرى هو ما يوقعكم في التأخير.</p><h3>الأب خارج تركيا — من يبلّغ؟</h3><p>المادة 15/5 تحلّ هذا: الواجب على الولي الحاضر، وعند الغياب على الجدّ أو الجدّة أو الإخوة البالغين أو من يكون الطفل عنده. غياب أحد الوالدين لا يعطّل القيد.</p>',
    steps = ARRAY['بلّغ عن الولادة خلال 30 يوماً: مديرية النفوس أو المشفى نفسه — وإن جرت الولادة في البيت فببيان شفهي للنفوس.', 'تحقّق بنفسك من أنّ قيد النفوس تمّ ولا تتّكل على تبليغ المشفى وحده.', 'اطلب بيان الولادة متعدد اللغات (Formül A) من النفوس في اليوم نفسه.', 'إن كنتم على الكملك: راجعوا مديرية الهجرة لإضافة الطفل وإصدار رقمه (99…) بأسرع ما يمكن.', 'وإن كنتم بإقامة: اسألوا المديرية عن ترتيب إقامة الطفل بحسب إقامتكما.', 'للشقّ السوري (القيد والجواز): اتبعوا ترتيب المراحل الست في دليل جواز الطفل — التصديق قبل البعثة.', 'احتفظوا بنسخ من كل وثيقة: تقرير المشفى، وFormül A، وما يصدر عن الهجرة.']::text[], tips = ARRAY['الثلاثون يوماً واجب قانوني — وفواتها لا يمنع القيد: سجّل فوراً ولو تأخّرت.', 'Formül A اطلبها بالاسم؛ هي ما تعتمده القنصليات، وطلبها لاحقاً مراجعة كاملة زائدة.', 'الولادة في تركيا لا تمنح الجنسية التركية — الطفل يتبع والديه.', 'صحة الطفل وتطعيماته معلّقة على رقمه — لا تؤجّلوا مراجعة الهجرة لحاملي الكملك.', 'لا تربطوا قيد الولادة بمعاملة أخرى (عنوان، تجديد) — كلٌّ في مساره.', 'غياب الأب لا يعطّل التبليغ: المادة 15/5 تسمّي من يقوم مقامه.']::text[], documents = ARRAY['تقرير الولادة من المشفى (Doğum Raporu) — أو بيان شفهي للنفوس إن كانت الولادة في البيت', 'هوية الوالدين: الكملك أو جواز السفر أو بطاقة الإقامة', 'بعد القيد: بيان الولادة متعدد اللغات (Formül A) من النفوس', 'لحاملي الكملك: كملك الوالدين لمراجعة مديرية الهجرة وإضافة الطفل']::text[],
    fees = 'قيد الولادة لدى النفوس مجاني. ولا رسم على التبليغ. وما يُدفع لاحقاً يخصّ معاملات أخرى (تصديق، قنصلية، جواز) في مساراتها — لا تدفعوا لوسيط مقابل «تسجيل المولود».', warning = 'التبليغ خلال 30 يوماً واجب المادة 15 من قانون 5490 — والتأخّر لا يمنع القيد فلا تؤجّلوا أكثر. والولادة في تركيا لا تمنح الجنسية. وترتيب الشقّ السوري له تسلسل صحيح يبدأ من القيد التركي — قفزُ مرحلةٍ يعيدكم إلى أولها.', source = 'قانون خدمات النفوس رقم 5490 — المادة 15 (فقرات 1 و2 و4 و5: مهلة الثلاثين يوماً، وواجب المشفى خلال 5 أيام عمل، والبيان الشفهي لولادة البيت، ومن يقع عليه التبليغ)؛ وبيان الولادة متعدد اللغات Formül A وفق تعميم المديرية العامة للنفوس؛ وإضافة المولود لقيد الحماية المؤقتة لدى مديريات إدارة الهجرة (goc.gov.tr)', tags = ARRAY['المواليد', 'تسجيل الولادة', 'الكملك والحماية المؤقتة', 'النفوس', 'دليل', '2026']::text[],
    category = 'خدمات السوريين', seo_title = 'تسجيل المولود في تركيا: مهلة 30 يوماً وFormül A خطوة بخطوة', seo_description = 'التبليغ إلزامي خلال 30 يوماً (المادة 15 من قانون 5490)، والمشفى ملزم خلال 5 أيام عمل، وFormül A هي الوثيقة التي تطلبها بالاسم — ثم إضافة الطفل للكملك أو ترتيب إقامته، والترتيب الصحيح للشق السوري.',
    last_update = CURRENT_DATE
WHERE slug = 'birth-registration-turkey';

-- رابط صفحة إجازة الأمومة يتحوّل من النقض المتقاعد إلى الدليل
UPDATE articles SET
    details = replace(details, '/article/family-birth-registration-flow', '/article/birth-registration-turkey'),
    last_update = CURRENT_DATE
WHERE slug = 'maternity-leave-turkey-analik-izni' AND details LIKE '%/article/family-birth-registration-flow%';

-- محاولة الأرشفة السابعة — والخطأ إن وقع يُقرأ هذه المرّة
DO $archive$
BEGIN
    PERFORM set_config('app.archive_err', '', false);
    UPDATE articles SET status = 'archived', last_update = CURRENT_DATE
     WHERE slug IN ('red-crescent-card', 'kizilay-card-problems', 'kizilay-card-apply', 'bank-account-documents', 'kimlik-bank-sim', 'kimlik-newborn-addition', 'family-birth-registration-flow') AND status = 'approved';
EXCEPTION WHEN others THEN
    PERFORM set_config('app.archive_err', SQLERRM, false);
END
$archive$;

-- ═══════════════════════════════════════════════════════════════════════════
DO $check$
DECLARE n int;
BEGIN
    SELECT count(*) INTO n FROM articles
     WHERE slug = 'birth-registration-turkey' AND status = 'approved'
       AND details LIKE '%Formül A%' AND details LIKE '%15/5%';
    IF n <> 1 THEN RAISE EXCEPTION 'the birth guide did not land'; END IF;

    SELECT count(*) INTO n FROM articles WHERE slug = 'birth-registration-turkey';
    IF n <> 1 THEN RAISE EXCEPTION 'duplicate slug — the upsert trap happened anyway'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'maternity-leave-turkey-analik-izni' AND details LIKE '%/article/family-birth-registration-flow%';
    IF n > 0 THEN RAISE EXCEPTION 'maternity still links the retired stub'; END IF;
END
$check$;

-- ── المراجعة: البنود + تشخيص الأرشفة ──────────────────────────────────────
SELECT 'birth guide rebuilt (law 5490 art 15 + Formül A)' AS البند,
       (details LIKE '%Formül A%' AND details LIKE '%30 يوماً%')::text AS النتيجة
FROM articles WHERE slug = 'birth-registration-turkey'
UNION ALL
SELECT 'maternity page now links the guide',
       (details LIKE '%/article/birth-registration-turkey%')::text
FROM articles WHERE slug = 'maternity-leave-turkey-analik-izni'
UNION ALL
SELECT 'stubs still approved (want 0)',
       count(*)::text
FROM articles WHERE slug IN ('red-crescent-card', 'kizilay-card-problems', 'kizilay-card-apply', 'bank-account-documents', 'kimlik-bank-sim', 'kimlik-newborn-addition', 'family-birth-registration-flow') AND status = 'approved'
UNION ALL
SELECT 'archive error text (empty = success)',
       COALESCE(NULLIF(current_setting('app.archive_err', true), ''), '(none)')
UNION ALL
SELECT 'CHECK constraints on articles',
       COALESCE(string_agg(conname || ': ' || pg_get_constraintdef(oid), ' | '), '(none)')
FROM pg_constraint WHERE conrelid = 'articles'::regclass AND contype = 'c'
UNION ALL
SELECT 'triggers on articles',
       COALESCE(string_agg(tgname, ', '), '(none)')
FROM pg_trigger WHERE tgrelid = 'articles'::regclass AND NOT tgisinternal;
